 * Designer: Behnam (X Series / Irmug) — https://fontlibrary.org/en/font/xb-shafigh-uzbek
 * Licensed under the SIL Open Font License, Version 1.1 — see LICENSE / OFL.txt.
 */

@font-face {
  font-family: "XB Shafigh Uzbek";
  src: url("./Shafigh-Regular.woff2") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "XB Shafigh Uzbek";
  src: url("./Shafigh-Bold.woff2") format("woff2");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "XB Shafigh Uzbek";
  src: url("./Shafigh-Italic.woff2") format("woff2");
  font-weight: 400;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "XB Shafigh Uzbek";
  src: url("./Shafigh-BoldItalic.woff2") format("woff2");
  font-weight: 700;
  font-style: italic;
  font-display: swap;
}
